.L.str.125:                             # @.str.125
	.asciz	"raw pointer return types are not allowed in safe Apollo function signatures"

.L.str.126:                             # @.str.126
	.asciz	"return a safe reference or owning type instead of a raw pointer"

.L.str.127:                             # @.str.127
	.asciz	"*"

.L.str.128:                             # @.str.128
	.asciz	"\nsuggested fix: "

.L.str.129:                             # @.str.129
	.asciz	"raw pointer return types are not allowed in safe Apollo method signatures"

.L.str.130:                             # @.str.130
	.asciz	"raw pointer fields are not allowed in safe Apollo type definitions"

.L.str.131:                             # @.str.131
	.asciz	"use a reference or safe owning type instead of a raw pointer field"

.L.str.132:                             # @.str.132
	.asciz	"raw pointer parameters are not allowed in safe Apollo function signatures"

.L.str.133:                             # @.str.133
	.asciz	"use a safe reference type or contain raw pointer interop inside `@unsafe {}` code"

.L.str.134:                             # @.str.134
	.asciz	"inline foreign code is only allowed inside `@unsafe {}` blocks"

.L.str.135:                             # @.str.135
	.asciz	"wrap this inline foreign block in `@unsafe { ... }`"

.L.str.136:                             # @.str.136
	.asciz	"native inline interop is only allowed inside `@unsafe {}` blocks"

.L.str.137:                             # @.str.137
	.asciz	"wrap this native block in `@unsafe { ... }`"

.L.str.138:                             # @.str.138
	.asciz	"raw pointer globals are not allowed in safe Apollo code"

.L.str.139:                             # @.str.139
	.asciz	"replace the global raw pointer with a safe type or isolate raw memory access inside `@unsafe {}` code paths"

.L.str.140:                             # @.str.140
	.asciz	"manual allocation is only allowed inside `@unsafe {}` blocks"

.L.str.141:                             # @.str.141
	.asciz	"wrap this allocation in `@unsafe { ... }` or switch to a safe managed value"

.L.str.142:                             # @.str.142
	.asciz	"`mnt` allocation is only allowed inside `@unsafe {}` blocks"

.L.str.143:                             # @.str.143
	.asciz	"placement reset is only allowed inside `@unsafe {}` blocks"

.L.str.144:                             # @.str.144
	.asciz	"wrap this reset in `@unsafe { ... }`"

.L.str.145:                             # @.str.145
	.asciz	"manual release is only allowed inside `@unsafe {}` blocks"

.L.str.146:                             # @.str.146
	.asciz	"wrap this release in `@unsafe { ... }`"

.L.str.147:                             # @.str.147
	.asciz	"placement allocation is only allowed inside `@unsafe {}` blocks"

.L.str.148:                             # @.str.148
	.asciz	"wrap this placement allocation in `@unsafe { ... }`"

.L.str.149:                             # @.str.149
	.asciz	"raw pointer aliasing is only allowed inside `@unsafe {}` blocks"

.L.str.150:                             # @.str.150
	.asciz	"wrap this pointer operation in `@unsafe { ... }`"

.L.str.151:                             # @.str.151
	.asciz	"raw pointer declarations are only allowed inside `@unsafe {}` blocks"

.L.str.152:                             # @.str.152
	.asciz	"replace the raw pointer with a safe reference or move the declaration into `@unsafe { ... }`"

.L.str.153:                             # @.str.153
	.asciz	" memory-safety error"

